ring_config:
struct RqC {
  static constexpr int XB = NT * 128, WB = 12288, ND = NT / 2;
  // rs128b: FL bits 8-15 = WS, a separate W ring of WS slots with its own full barriers (0: W shares the x slots)
  static constexpr bool SPLITF = ((FL >> 8) & 255) != 0;
  static constexpr int WS = SPLITF ? ((FL >> 8) & 255) : ST;
  static constexpr int SMEM = 1024 + ST * XB + WS * WB + 8 * (2 * ST + 2 * WS) + 16;
};

ring_bases:
constexpr bool SPLITF = C::SPLITF;
constexpr int WS = C::WS;
const uint32_t xring = sbase, wring = sbase + ST * XB, bars = wring + WS * WB;
// full[ST] (x + W, or x only when SPLITF) | wempty[WS] | xempty[ST] | wfull[WS] | zflag
const uint32_t full = bars, wempty = bars + 8 * ST, xempty = wempty + 8 * WS, wfull0 = xempty + 8 * ST, zflag = wfull0 + 8 * WS;
const uint32_t wfull = SPLITF ? wfull0 : full;

W_producer:
if (warp == 8 && lane == 0 && WON) {
  const int nbw = p.walias ? nb % p.walias : nb;
  const uint8_t* src = p.W + ((size_t)nbw * p.KC + s0) * WB;
  uint64_t pol = 0;
  if (HINT) asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;\n" : "=l"(pol));
  unsigned long long tw = 0;
  int slot = 0, r = 0;
  for (int s = 0; s < KCS; s++) {
    if (s >= WS) {
      const unsigned long long t0 = INS ? clock64() : 0;
      rq_wait((SELF ? wfull : wempty) + 8 * slot, (r & 1) ^ 1);
      if (INS) tw += clock64() - t0;
    }
    rq_expect(wfull + 8 * slot, WB);
    if (HINT) rq_bulkh(wring + slot * WB, src + (size_t)s * WB, WB, wfull + 8 * slot, pol);
    else rq_bulk(wring + slot * WB, src + (size_t)s * WB, WB, wfull + 8 * slot);
    if (++slot == WS) { slot = 0; r++; }
  }
  if (SELF && (!XON || SPLITF)) for (int s = (KCS > WS ? KCS - WS : 0); s < KCS; s++) rq_wait(wfull + 8 * (s % WS), (s / WS) & 1);
  if (INS) { p.prof[cta * 32 + 9] = tw; p.prof[cta * 32 + 15] = rq_gt(); }

W_read_release:
  auto ldr = [&](int G) {  // full waits, LDS of this warp's 48 B per lane per stage, W slots released
#pragma unroll
    for (int j = 0; j < GS; j++) {
      const int s = GS * G + j;
      if (s < KCS) {
        const int slot = RES ? 0 : s % WS;
        if (!RES) rq_wait(wfull + 8 * slot, (s / WS) & 1);
        if (!RES && SPLITF && (PRB == 1 || PRB == 2 || PRB == 3)) rq_wait(full + 8 * (s % ST), (s / ST) & 1);  // probes: x here
        if (PRB != 1 && PRB != 2) {
          const uint32_t a = wl + slot * WB;
          Q[j][0] = rq_lds(a); Q[j][1] = rq_lds(a + 512); Q[j][2] = rq_lds(a + 1024);
        }
      }
    }
    RQ_T1(1);
    if (!RES) {
      __syncwarp();
      if (lane == 0) {
#pragma unroll
        for (int j = 0; j < GS; j++) if (GS * G + j < KCS) rq_arrive(wempty + 8 * ((GS * G + j) % WS));
      }
    }
    RQ_T1(2);
  };

X_full_wait:
  auto mma = [&](int G, auto NSC, uint32_t (&A)[GS][16]) {  // NSC: compile-time stage count of this round
    constexpr int NS = decltype(NSC)::value;
    if (SPLITF && !RES) {
#pragma unroll
      for (int j = 0; j < NS; j++) { const int s = GS * G + j; rq_wait(full + 8 * (s % ST), (s / ST) & 1); }
    }
